hawking.current-commutator-exactly-edge-:
"""hawking.current-commutator-exactly-edge-split: exact checks.

Finite window of L fermionic modes 1..L (stored as bits 0..L-1 of a Fock bitmask, Jordan-Wigner signs),
currents a_m = sum_{k=1}^{L-m} psi_k^dagger psi_{k+m}, N_k = psi_k^dagger psi_k. Operators are applied to
every basis state, so each identity is an operator identity on the whole Fock space.
(1) [a_m, a_m^dagger] = B_m - T_m on all 2^L states, for every m = 1..L-1, L = 6 and 7.
(2) For 2m <= L, on every edge-clean state (bottom m filled, top m empty) [a_m, a_m^dagger] = m.
(3) [a_m, a_m'] = 0 for all m, m' (L = 6, all states).
(4) For m != m' the one-body matrix of [a_m, a_m'^dagger] (the commutator of the shift matrices) has
    every nonzero entry (a, b) with a, b both among the lowest max(m, m') modes or both among the highest
    max(m, m'), its second quantisation is the Fock commutator (checked on all states), and it annihilates
    every state edge-clean at depth max(m, m').
"""
from fractions import Fraction as F

import GA

WINDOWS = [6, 7]


def basis_state(s):
    """The Fock basis state with occupation bitmask s, coefficient 1."""
    return {s: F(1)}


def popcount(s):
    return bin(s).count("1")


def bilin(a, b, vec):
    """psi_a^dagger psi_b on a state {mask: coeff} (0-indexed modes)."""
    out = {}
    for s, c in vec.items():
        if not (s >> b) & 1:
            continue
        sg = -1 if popcount(s & ((1 << b) - 1)) % 2 else 1
        s1 = s & ~(1 << b)
        if (s1 >> a) & 1:
            continue
        sg *= -1 if popcount(s1 & ((1 << a) - 1)) % 2 else 1
        s2 = s1 | (1 << a)
        out[s2] = out.get(s2, F(0)) + sg * c
    return {k: v for k, v in out.items() if v != 0}


def apply_sum(terms, vec):
    """terms: list of (coeff, a, b) meaning sum coeff psi_a^dagger psi_b."""
    out = {}
    for (c, a, b) in terms:
        for s, v in bilin(a, b, vec).items():
            out[s] = out.get(s, F(0)) + c * v
    return {k: v for k, v in out.items() if v != 0}


def comm(t1, t2, vec):
    x = apply_sum(t1, apply_sum(t2, vec))
    y = apply_sum(t2, apply_sum(t1, vec))
    for s, v in y.items():
        x[s] = x.get(s, F(0)) - v
    return {k: v for k, v in x.items() if v != 0}


def cur(m, L, dagger=False):
    if dagger:
        return [(F(1), k + m, k) for k in range(L - m)]
    return [(F(1), k, k + m) for k in range(L - m)]


def check_commutator_is_edge_difference():
    n_cases = 0
    for L in WINDOWS:
        for m in range(1, L):
            Bm = [(F(1), k, k) for k in range(m)]
            Tm = [(F(-1), k, k) for k in range(L - m, L)]
            for s in range(1 << L):
                v = basis_state(s)
                assert comm(cur(m, L), cur(m, L, True), v) == apply_sum(Bm + Tm, v)
                n_cases += 1
    # every m = 1..L-1 on all 2^L states: (L - 1) 2^L summed over L = 6, 7 is 5 * 64 + 6 * 128 = 1088
    assert n_cases == 1088
    return True


def check_edge_clean_scalar():
    for L in WINDOWS:
        for m in range(1, L // 2 + 1):
            n_clean = 0
            for s in range(1 << L):
                if all((s >> k) & 1 for k in range(m)) and not any((s >> k) & 1 for k in range(L - m, L)):
                    n_clean += 1
                    assert comm(cur(m, L), cur(m, L, True), {s: F(1)}) == {s: F(m)}
            assert n_clean == 2 ** (L - 2 * m)
    return True


def check_currents_commute():
    L = 6
    for m in range(1, L):
        for mp in range(1, L):
            for s in range(1 << L):
                assert comm(cur(m, L), cur(mp, L), {s: F(1)}) == {}
    # contrast: with the adjoint the commutator is not zero, e.g. N_1 - N_6 on the state with mode 1 filled
    assert comm(cur(1, L), cur(1, L, True), {1: F(1)}) == {1: F(1)}
    return True


def check_cross_commutator_edge_supported():
    L = 7
    for m in range(1, 4):
        for mp in range(1, 4):
            if m == mp:
                continue
            d = max(m, mp)
            # one-body matrices h[a][b] (coefficient of psi_a^dagger psi_b)
            h1 = [[F(1) if b == a + m else F(0) for b in range(L)] for a in range(L)]
            h2 = [[F(1) if a == b + mp else F(0) for b in range(L)] for a in range(L)]
            hc = [[sum((h1[a][k] * h2[k][b] - h2[a][k] * h1[k][b] for k in range(L)), F(0))
                   for b in range(L)] for a in range(L)]
            low, high = set(range(d)), set(range(L - d, L))
            nz = [(a, b) for a in range(L) for b in range(L) if hc[a][b] != 0]
            assert nz and all((a in low and b in low) or (a in high and b in high) for (a, b) in nz)
            assert all(a != b for (a, b) in nz)
            terms = [(hc[a][b], a, b) for (a, b) in nz]
            for s in range(1 << L):
                v = {s: F(1)}
                assert comm(cur(m, L), cur(mp, L, True), v) == apply_sum(terms, v)
                if all((s >> k) & 1 for k in range(d)) and not any((s >> k) & 1 for k in range(L - d, L)):
                    assert apply_sum(terms, v) == {}
    return True

hawking.helicity-lift-joints-itemised:
"""hawking.helicity-lift-joints-itemised: exact checks of the computable joints.

J1 (Fact hawking.imported-penrose-transform): helicity s <-> homogeneity -2s - 2; the table: photon s = +1, -1 at
    -4, 0 and graviton s = +2, -2 at -6, +2, and the map s -> -2s - 2 is injective with inverse h -> -(h + 2)/2.
J2 (Proposition hawking.homogeneity-ordering-shift with the shift of Fact
    hawking.imported-twistor-storey-ordering-shift): on polynomials in Z^0..Z^3, Zbar_a = -d/dZ^a (hbar = 1),
    q(id) = 1/2 sum_a (Z^a Zbar_a + Zbar_a Z^a) equals -(Upsilon + 2) on every monomial of degree <= 3, so a
    homogeneous function of degree h has helicity s = q(id)/2 eigenvalue -(h + 2)/2; the offset -2 is the
    ordering shift (the normal-ordered generator sum Z^a Zbar_a gives -Upsilon, no offset).
J3 (the s-wave reduction) is a modelling joint with no computable content and is not checked.
"""
import GA
from fractions import Fraction as F
from itertools import product

from tp_premise import premise

HELICITIES = [(1, "photon"), (-1, "photon"), (2, "graviton"), (-2, "graviton")]


def check_homogeneity_table():
    premise("hawking.imported-penrose-transform")
    table = {s: -2 * s - 2 for s, _ in HELICITIES}
    ok = table == {1: -4, -1: 0, 2: -6, -2: 2}
    ok = ok and all(F(-(h + 2), 2) == s for s, h in table.items())
    ok = ok and len(set(table.values())) == 4
    _tp_rv = (ok); assert _tp_rv is not False, "check_homogeneity_table"; return _tp_rv


def mono_Z(a, f):
    out = {}
    for ex, c in f.items():
        e = list(ex)
        e[a] += 1
        out[tuple(e)] = out.get(tuple(e), F(0)) + c
    return out


def mono_Zbar(a, f):
    out = {}
    for ex, c in f.items():
        if ex[a] == 0:
            continue
        e = list(ex)
        e[a] -= 1
        out[tuple(e)] = out.get(tuple(e), F(0)) - c * ex[a]
    return out


def add_into(out, f, coef):
    for ex, c in f.items():
        out[ex] = out.get(ex, F(0)) + coef * c


def check_helicity_is_the_shifted_euler_charge():
    premise("hawking.homogeneity-ordering-shift")
    premise("hawking.imported-twistor-storey-ordering-shift")
    ok = True
    count = 0
    for ex in product(range(4), repeat=4):
        deg = sum(ex)
        if deg > 3:
            continue
        f = {ex: F(1)}
        sym, normal = {}, {}
        for a in range(4):
            add_into(sym, mono_Z(a, mono_Zbar(a, f)), F(1, 2))
            add_into(sym, mono_Zbar(a, mono_Z(a, f)), F(1, 2))
            add_into(normal, mono_Z(a, mono_Zbar(a, f)), F(1))
        ok = ok and sym == {ex: F(-(deg + 2))} and normal == ({ex: F(-deg)} if deg else {})
        ok = ok and sym[ex] / 2 == F(-(deg + 2), 2)
        count += 1
    _tp_rv = (ok and count == 35); assert _tp_rv is not False, "check_helicity_is_the_shifted_euler_charge"; return _tp_rv

hawking.homogeneity-ordering-shift:
"""hawking.homogeneity-ordering-shift: exact checks.

Polynomials in n complex variables Z^0..Z^{n-1} (dicts exponent tuple -> Fraction), with Z^mu acting by
multiplication and Zbar_nu = -hbar d/dZ^nu, at exact sample values of hbar. A first-order differential
operator with coefficients of degree <= 1 is fixed by its values on monomials of degree <= 1; all monomials
of degree <= 4 are used.
(a) The realisation satisfies the palatial sign [Z^mu, Zbar_nu] = +hbar delta^mu_nu.
(b) q(id) = (1/2) sum (Z^a Zbar_a + Zbar_a Z^a) equals -hbar(Upsilon + 2) for n = 4 (twistor space C^4),
    and -hbar(Upsilon + n/2) for n = 1..4: the offset is one half per complex dimension.
(c) On a homogeneous polynomial of degree h, s = q(id)/2 has eigenvalue -(h + 2) hbar/2, so the helicity
    s hbar occurs iff h = -2s - 2 (table s = 1, -1, 2, -2, 1/2, -1/2 gives h = -4, 0, -6, 2, -3, -1); an
    inhomogeneous sum is not an eigenfunction.
(d) Without the symmetric-ordering shift (normal ordering sum Z^a Zbar_a) the operator is -hbar Upsilon and
    the offset vanishes (h = -2s); the opposite-sign realisation Zbar = +hbar d/dZ flips it to h = 2s + 2.
"""
from fractions import Fraction as F
from itertools import product

import GA
from tp_premise import premise

HBARS = [F(1), F(3, 2), F(-2, 7)]
TWISTOR_N = 4                 # twistor space C^4: (b) at n = 4 on all monomials of degree <= 4
TWISTOR_MAXDEG = 4
DIMS = range(1, 5)            # (b) for n = 1..4 on all monomials of degree <= DIMS_MAXDEG
DIMS_MAXDEG = 3


def unit_mono(e):
    """The monomial Z^e with coefficient 1."""
    return {e: F(1)}


def monos(n, maxdeg):
    return [e for e in product(range(maxdeg + 1), repeat=n) if sum(e) <= maxdeg]


def padd(f, g, c=F(1)):
    out = dict(f)
    for k, v in g.items():
        out[k] = out.get(k, F(0)) + c * v
    return {k: v for k, v in out.items() if v != 0}


def mulZ(a, f):
    out = {}
    for e, c in f.items():
        e2 = list(e)
        e2[a] += 1
        out[tuple(e2)] = out.get(tuple(e2), F(0)) + c
    return out


def dZ(a, f):
    out = {}
    for e, c in f.items():
        if e[a]:
            e2 = list(e)
            e2[a] -= 1
            out[tuple(e2)] = out.get(tuple(e2), F(0)) + e[a] * c
    return out


def Zbar(a, f, hbar, sign=-1):
    return {k: sign * hbar * v for k, v in dZ(a, f).items()}


def q_id(f, n, hbar, sign=-1):
    out = {}
    for a in range(n):
        out = padd(out, mulZ(a, Zbar(a, f, hbar, sign)), F(1, 2))
        out = padd(out, Zbar(a, mulZ(a, f), hbar, sign), F(1, 2))
    return out


def euler(f, n):
    out = {}
    for a in range(n):
        out = padd(out, mulZ(a, dZ(a, f)))
    return out


def check_palatial_sign_of_realisation():
    premise("hawking.imported-twistor-storey-ordering-shift")
    n = 4
    for hbar in HBARS:
        for e in monos(n, 3):
            f = {e: F(1)}
            for mu in range(n):
                for nu in range(n):
                    c = padd(mulZ(mu, Zbar(nu, f, hbar)), Zbar(nu, mulZ(mu, f), hbar), F(-1))
                    assert c == ({e: hbar} if mu == nu else {})
    return True


def check_charge_is_minus_hbar_euler_plus_two():
    premise("hawking.imported-twistor-storey-ordering-shift")
    for hbar in HBARS:
        for e in monos(TWISTOR_N, TWISTOR_MAXDEG):
            f = unit_mono(e)
            q = q_id(f, TWISTOR_N, hbar)
            assert q == padd({k: -hbar * v for k, v in euler(f, TWISTOR_N).items()}, f, -2 * hbar)
        for n in DIMS:
            for e in monos(n, DIMS_MAXDEG):
                f = unit_mono(e)
                rhs = padd({k: -hbar * v for k, v in euler(f, n).items()}, f, -hbar * F(n, 2))
                assert q_id(f, n, hbar) == rhs
    return True


def check_homogeneity_iff_helicity():
    premise("hawking.imported-twistor-storey-ordering-shift")
    hbar = HBARS[1]
    for h in range(0, 5):
        hom = [e for e in monos(4, h) if sum(e) == h]
        f = {}
        for i, e in enumerate(hom):
            f[e] = F(i + 1)
        sf = {k: v / 2 for k, v in q_id(f, 4, hbar).items()}
        lam = -F(h + 2, 2) * hbar
        assert sf == {k: lam * v for k, v in f.items()}
        s = lam / hbar
        assert h == -2 * s - 2
    table = {F(1): -4, F(-1): 0, F(2): -6, F(-2): 2, F(1, 2): -3, F(-1, 2): -1}
    for s, h in table.items():
        assert -2 * s - 2 == h
    g = {(1, 0, 0, 0): F(1), (0, 0, 0, 0): F(1)}
    sg = {k: v / 2 for k, v in q_id(g, 4, hbar).items()}
    assert GA.rank_of_vectors([[sg.get(k, F(0)) for k in sorted(g)], [g[k] for k in sorted(g)]]) == 2
    return True


def check_offset_is_the_ordering_shift():
    premise("hawking.imported-twistor-storey-ordering-shift")
    for hbar in HBARS:
        for e in monos(4, 3):
            f = {e: F(1)}
            normal = {}
            for a in range(4):
                normal = padd(normal, mulZ(a, Zbar(a, f, hbar)))
            assert normal == {k: -hbar * v for k, v in euler(f, 4).items()}
            shift = padd(q_id(f, 4, hbar), normal, F(-1))
            assert shift == {e: -2 * hbar}
            # opposite realisation Zbar = +hbar d/dZ: q(id) = +hbar(Upsilon + 2), so h = 2s + 2
            flipped = q_id(f, 4, hbar, sign=1)
            assert flipped == padd({k: hbar * v for k, v in euler(f, 4).items()}, f, 2 * hbar)
    return True

hawking.imported-algebra-boundary-modes-:
"""hawking.imported-algebra-boundary-modes-car-algebra: exact checks of the finite core.

The completed limit and the CAR uniqueness are the cited theorems (tower.algebraic-limit-even-charge,
tower.car-limit-even-charge) and have no finite content here. Checked on the physical lineage, the
tower over Cl(1,3) (GA.py: ground generators first, then plane j as e_j (+1), f_j (-1),
v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2):
(1) the transport charge p - q mod 8 of every floor Cl(1+k, 3+k), k = 0..6, is 6, even;
(2) the mode operators are the adjoined null pairs: they satisfy the CAR exactly in T_k (k <= 3),
    v_j^* = w_j for the *-antiautomorphism (x* = x for x^2 = 1, x* = -x for x^2 = -1), and they
    commute with the twisted ground generators, which satisfy the Cl(1,3) relations; the mode
    algebra generated by the v_j, w_j contains e_j = v_j + w_j and f_j = v_j - w_j, and the products
    of the ordered ground words with the ordered mode words hit all 2^(4 + 2k) blades of the floor
    (k <= 3), so the floor is the ground factor tensored with the mode algebra (16 * 4^k = dim);
    at k = 1 the same is shown directly from the words in v_1, w_1 (rank 64);
(3) the Fock adjointness: the images rho(e_j) = wedge + contraction, rho(f_j) = wedge - contraction
    on Lambda W_k (orthonormal wedge monomials) satisfy the Cl(k,k) relations; extending rho to
    the Clifford element v_j (as a sum of blades) gives the wedge by v_j, and rho(x^*) is the
    transpose of rho(x) for every blade x of Cl(k,k) (k <= 2), in particular for w_j = v_j^* (k <= 3);
    the vacuum is annihilated by every rho(w_j) and by no rho(v_j).
The labelling checked is the statement's and the premise's (tower.car-limit-even-charge):
annihilation a_j = v_j^* = w_j, creation a_j^dagger = v_j.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

# ---------------------------------------------------------------------------
# Exact Clifford helpers on top of GA.py (elements are dicts {blade: Fraction}).
# ---------------------------------------------------------------------------


def blade_el(b, c=1):
    return {tuple(b): F(c)} if c else {}


def prod(xs, sq):
    out = GA.sc(1)
    for x in xs:
        out = GA.mul(out, x, sq)
    return out


def coords(x, n):
    return [x.get(b, F(0)) for b in GA.all_blades(n)]


def span_rank(els, n):
    els = [e for e in els if not GA.is_zero(e)]
    return GA.rank_of_vectors([coords(e, n) for e in els]) if els else 0


def words(gens, sq):
    """The ordered products of all subsets of gens: they span the generated subalgebra
    when the generators pairwise anticommute and square to nonzero scalars."""
    out = []
    for r in range(len(gens) + 1):
        for idx in combinations(range(len(gens)), r):
            out.append(prod([gens[i] for i in idx], sq))
    return out


def scalar_of(x):
    """x as a scalar if it is one, else None."""
    if GA.is_zero(x):
        return F(0)
    if set(x) == {()}:
        return x[()]
    return None


def anticommuting_with_squares(gens, sq):
    """The list of squares if the gens pairwise anticommute and square to scalars, else None."""
    out = []
    for i, g in enumerate(gens):
        s = scalar_of(GA.mul(g, g, sq))
        if s is None:
            return None
        out.append(s)
        for h in gens[i + 1:]:
            if not GA.anticommutes(g, h, sq):
                return None
    return out


def volume(n, sq):
    return prod([GA.gen(i) for i in range(n)], sq)


def is_central(x, n, sq):
    return all(GA.commutes(x, GA.gen(i), sq) for i in range(n))


def corner(f, basis, sq, n):
    """An independent spanning list of f b f, b in basis."""
    out, vecs = [], []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if GA.is_zero(y):
            continue
        v = coords(y, n)
        if GA.rank_of_vectors(vecs + [v]) > len(vecs):
            vecs.append(v)
            out.append(y)
    return out


def corner_division_type(f, basis, sq, n):
    """'R', 'C' or 'H' when f is an idempotent whose corner f A f is that division algebra
    (exact: R = span{f}; C = f plus an element squaring to -f; H = quaternion units i, j,
    i j with i^2 = j^2 = -f, i j = -j i), else None. A division corner makes f primitive,
    so the letter is the Wedderburn division algebra of the simple algebra A."""
    if not GA.eq(GA.mul(f, f, sq), f):
        return None
    cb = corner(f, basis, sq, n)
    if len(cb) == 1:
        return "R"
    roots = []
    for b in basis:
        y = GA.mul(GA.mul(f, b, sq), f, sq)
        if not GA.is_zero(y) and GA.eq(GA.mul(y, y, sq), GA.neg(f)):
            roots.append(y)
    if len(cb) == 2 and roots:
        return "C"
    if len(cb) == 4:
        for i, a in enumerate(roots):
            for c in roots[i + 1:]:
                if GA.is_zero(GA.add(GA.mul(a, c, sq), GA.mul(c, a, sq))):
                    if span_rank([f, a, c, GA.mul(a, c, sq)], n) == 4:
                        return "H"
    return None


def idempotent_from(us, sq):
    """prod (1 + u)/2 over commuting elements u with u^2 = 1."""
    f = GA.sc(1)
    for u in us:
        f = GA.mul(f, GA.scal(F(1, 2), GA.add(GA.sc(1), u)), sq)
    return f


def simple_copy_type(gens, sq, n):
    """For a simple subalgebra spanned by words(gens): (k, D) with the subalgebra Mat_k(D),
    found from an idempotent f = prod (1 + u)/2 (u words squaring to 1, commuting) whose corner
    is a division algebra; dim = k^2 dim D is asserted. None if no such f is found."""
    basis = words(gens, sq)
    dim = span_rank(basis, n)
    units = [u for u in basis if scalar_of(u) is None and GA.eq(GA.mul(u, u, sq), GA.sc(1))]
    trials = [[]] + [[u] for u in units]
    trials += [[u, v] for i, u in enumerate(units) for v in units[i + 1:] if GA.commutes(u, v, sq)]
    for us in trials:
        f = idempotent_from(us, sq)
        if GA.is_zero(f):
            continue
        d = corner_division_type(f, basis, sq, n)
        if d is None:
            continue
        dd = {"R": 1, "C": 2, "H": 4}[d]
        k = 1
        while k * k * dd < dim:
            k += 1
        assert k * k * dd == dim
        return (k, d)
    return None
# ---------------------------------------------------------------------------
# Floors of the tower in GA.py: T_k over Cl(p,q) has the ground generators 0..n-1 (p squares +1,
# then q squares -1) and plane j (0-based) at n + 2j (e_j, square +1), n + 2j + 1 (f_j, square -1).
# v_j = (e_j + f_j)/2, w_j = (e_j - f_j)/2, omega_j = e_j f_j, Omega_k = omega_1 ... omega_k.
# ---------------------------------------------------------------------------


def floor_sq(p, q, k):
    return tuple([1] * p + [-1] * q + [1, -1] * k)


def plane(n, j):
    e, f = GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1)
    return GA.scal(F(1, 2), GA.add(e, f)), GA.scal(F(1, 2), GA.sub(e, f))


def big_omega(n, k, sq):
    return prod([GA.mul(GA.gen(n + 2 * j), GA.gen(n + 2 * j + 1), sq) for j in range(k)], sq)


def twisted_ground(n, k, sq):
    Om = big_omega(n, k, sq)
    return [GA.mul(GA.gen(i), Om, sq) for i in range(n)]


def matrix_units(n, k, sq):
    """E[(S, T)] = v_S f v_T^dagger, S, T subsets of the k planes, f = prod_j w_j v_j the vacuum
    projector and v_T^dagger the reversed product of the w's; the Fock-basis matrix units of B_k."""
    vs, ws = zip(*[plane(n, j) for j in range(k)]) if k else ((), ())
    f = prod([GA.mul(ws[j], vs[j], sq) for j in range(k)], sq)
    subsets = [S for r in range(k + 1) for S in combinations(range(k), r)]
    E = {}
    for S in subsets:
        left = prod([vs[j] for j in S], sq)
        for T in subsets:
            right = prod([ws[j] for j in reversed(T)], sq)
            E[(S, T)] = GA.mul(GA.mul(left, f, sq), right, sq)
    return subsets, E


def matrix_units_ok(subsets, E, sq):
    one = GA.add(*[E[(S, S)] for S in subsets])
    if not GA.eq(one, GA.sc(1)):
        return False
    for (S, T), x in E.items():
        for (U, W), y in E.items():
            want = E[(S, W)] if T == U else {}
            if not GA.eq(GA.mul(x, y, sq), want):
                return False
    return True


def tensor_blades(gens_a, gens_b, sq):
    """Products of the ordered words of gens_a with those of gens_b, when every one is a single
    basis blade: the set of blades hit (None if some product is not a single blade)."""
    seen = set()
    for a in words(gens_a, sq):
        for b in words(gens_b, sq):
            x = GA.mul(a, b, sq)
            if len(x) != 1:
                return None
            seen.add(next(iter(x)))
    return seen
# ---------------------------------------------------------------------------
# The Fock module Lambda W_k in the occupation basis: states are bitmasks 0 .. 2^k - 1, bit j set
# when v_j is present; the wedge monomial basis v_{j1} ^ ... ^ v_{jr} (j1 < ... < jr) is
# orthonormal. v_j acts by wedge (sign (-1)^(occupied modes below j)), w_j by contraction.
# Operators are sparse matrices {(row, col): Fraction}.
# ---------------------------------------------------------------------------


def k_wedge(j, k):
    return {(s | 1 << j, s): F((-1) ** bin(s & ((1 << j) - 1)).count("1"))
            for s in range(2 ** k) if not s >> j & 1}


def k_contract(j, k):
    return {(s & ~(1 << j), s): F((-1) ** bin(s & ((1 << j) - 1)).count("1"))
            for s in range(2 ** k) if s >> j & 1}


def smm(*Ms):
    out = Ms[0]
    for B in Ms[1:]:
        rows = {}
        for (r, c), x in B.items():
            get_or_set(rows, r, []).append((c, x))
        acc = {}
        for (r, t), x in out.items():
            for c, y in rows.get(t, ()):
                acc[(r, c)] = acc.get((r, c), 0) + x * y
        out = {key: v for key, v in acc.items() if v}
    return out


def sadd(*Ms):
    acc = {}
    for M in Ms:
        for key, x in M.items():
            acc[key] = acc.get(key, 0) + x
    return {key: v for key, v in acc.items() if v}


def ssc(c, A):
    return {key: c * x for key, x in A.items() if c * x}


def str_(A):
    return {(c, r): x for (r, c), x in A.items()}


def sident(d):
    return {(s, s): F(1) for s in range(d)}


def plane_images(k):
    """rho(e_j) = wedge + contraction, rho(f_j) = wedge - contraction, in GA generator order."""
    out = []
    for j in range(k):
        a, b = k_wedge(j, k), k_contract(j, k)
        out += [sadd(a, b), sadd(a, ssc(-1, b))]
    return out


def flat(M, d):
    return [M.get((r, c), F(0)) for r in range(d) for c in range(d)]


def star_blade(b, sq):
    out = GA.sc(1)
    for i in reversed(b):
        out = GA.mul(out, GA.scal(sq[i], GA.gen(i)), sq)
    return out


def star(x, sq):
    return GA.add(*[GA.scal(c, star_blade(b, sq)) for b, c in x.items()]) if x else {}


def check_physical_lineage_has_even_charge_six():
    premise("tower.algebraic-limit-even-charge")
    charges = {((1 + k) - (3 + k)) % 8 for k in range(7)}
    sq = floor_sq(1, 3, 0)
    p = sum(1 for i in range(4) if GA.eq(GA.mul(GA.gen(i), GA.gen(i), sq), GA.sc(1)))
    ok = charges == {6} and (p - (4 - p)) % 8 == 6 and 6 % 2 == 0
    GA.check("the physical lineage Cl(1+k, 3+k) has transport charge 6 at every floor", ok)
    return ok


def check_mode_operators_are_the_null_pairs():
    premise("tower.ladder-pairs-satisfy-car-vectors")
    premise("tower.car-limit-even-charge")
    ok = True
    for k in (1, 2, 3):
        sq = floor_sq(1, 3, k)
        pairs = [plane(4, j) for j in range(k)]
        tw = twisted_ground(4, k, sq)
        ok = ok and anticommuting_with_squares(tw, sq) == [1, -1, -1, -1]
        for i, (vi, wi) in enumerate(pairs):
            ok = ok and GA.eq(star(vi, sq), wi) and GA.eq(star(wi, sq), vi)
            ok = ok and all(GA.commutes(x, y, sq) for x in tw for y in (vi, wi))
            for j, (vj, wj) in enumerate(pairs):
                ok = ok and GA.is_zero(GA.add(GA.mul(vi, vj, sq), GA.mul(vj, vi, sq)))
                ok = ok and GA.is_zero(GA.add(GA.mul(wi, wj, sq), GA.mul(wj, wi, sq)))
                ac = GA.add(GA.mul(wi, vj, sq), GA.mul(vj, wi, sq))
                ok = ok and GA.eq(ac, GA.sc(1) if i == j else {})
        # the floor is the ground copy tensored with the mode algebra: e_j, f_j lie in the mode
        # algebra, and ground words times mode words hit every blade of Cl(1 + k, 3 + k)
        efs = []
        for j, (vj, wj) in enumerate(pairs):
            ej, fj = GA.add(vj, wj), GA.sub(vj, wj)
            ok = ok and GA.eq(ej, GA.gen(4 + 2 * j)) and GA.eq(fj, GA.gen(4 + 2 * j + 1))
            efs += [ej, fj]
        hit = tensor_blades(tw, efs, sq)
        ok = ok and hit is not None and len(hit) == 16 * 4 ** k == 2 ** (4 + 2 * k)
        if k == 1:
            vw = [x for pr in pairs for x in pr]
            prods = [GA.mul(a, b, sq) for a in words(tw, sq) for b in words(vw, sq)]
            ok = ok and span_rank(prods, 4 + 2 * k) == 64
    GA.check("the adjoined null pairs satisfy the CAR, v_j* = w_j, commute with the ground copy, "
             "and with it generate the floor", ok)
    return ok


def rho(x, imgs, d):
    """The Fock-module image of a Clifford element x (dict of blades) from generator images."""
    out = {}
    for b, c in x.items():
        out = sadd(out, ssc(c, smm(sident(d), *[imgs[i] for i in b])))
    return out


def check_fock_adjointness():
    premise("tower.car-limit-even-charge")
    ok = True
    for k in (1, 2, 3):
        d = 2 ** k
        sq = floor_sq(0, 0, k)
        imgs = plane_images(k)
        # rho is a representation of Cl(k, k): generator squares and anticommutators
        for a in range(2 * k):
            for b in range(2 * k):
                ab = sadd(smm(imgs[a], imgs[b]), smm(imgs[b], imgs[a]))
                ok = ok and ab == (ssc(2 * sq[a], sident(d)) if a == b else {})
        vac = {(0, 0): F(1)}
        for j in range(k):
            vj, wj = plane(0, j)
            rv, rw = rho(vj, imgs, d), rho(wj, imgs, d)
            ok = ok and rv == k_wedge(j, k) and rw == k_contract(j, k)
            ok = ok and rho(star(vj, sq), imgs, d) == rw == str_(rv)
            ok = ok and not smm(rw, vac) and smm(rv, vac) == {(1 << j, 0): F(1)}
        if k <= 2:
            for b in GA.all_blades(2 * k):
                x = blade_el(b)
                ok = ok and rho(star(x, sq), imgs, d) == str_(rho(x, imgs, d))
    GA.check("rho(x*) is the transpose of rho(x); w_j acts as the transpose of v_j; "
             "the vacuum is killed by every w_j and by no v_j", ok)
    return ok

hawking.imported-s-wave-bosonic-sector:
"""hawking.imported-s-wave-bosonic-sector: exact checks of both halves on finite windows.

Fermionic window on bitmask states (Jordan-Wigner signs), currents a_m = sum_i psi_i^dag psi_{i+m} (m > 0),
a_m^dag = sum_i psi_{i+m}^dag psi_i; weights w_k = kappa k with k = i - 3 on a 7-mode window.
Unconditional half.
(1) The exact finite-window identity [a_m, a_m^dag] = B_m - T_m (edge operators, Fact
    singularity.bosonisation-bridge-s-wave-sector (1)) on all 2^7 states for m = 1, 2, 3; hence the free-boson value m
    on edge-clean states.
(2) The bilinear subalgebra is invariant under the modular boost: [K, psi_i^dag psi_j] = (w_i - w_j) psi_i^dag psi_j
    for all i, j and every state, for the s-wave weights and also for non-affine weights (invariance of the
    bilinear span needs no affine law; the currents being weight vectors does, Fact
    singularity.bosonisation-bridge-s-wave-sector).
Conditional half, under (Q).
(3) The product Fermi-Dirac state (n_k = 1/(x^{-k} + 1), x = e^{-beta kappa}) is the Gibbs state of K, and its
    restriction to the current algebra is KMS: omega(a_m B) = x^{-m} omega(B a_m) on sample current products
    (an instance of Lemma hawking.kms-restricts-invariant-subalgebras).
(4) Bose-Einstein occupancy: the detailed-balance identity n_k - n_{k+m} = (x^{-m} - 1) n_{k+m}(1 - n_k) at sample
    x and k; on the window the density-matrix value of <a_m^dag a_m> equals the Wick sum sum n_{k+m}(1 - n_k); the
    window sums equal (edge numerator)/(x^{-m} - 1) exactly and approach m/(x^{-m} - 1) = m nbar(m kappa) from
    below within 2 m x^{K-m}/(1 - x); and nbar/(1 + nbar) = x^m (Bose-Einstein detailed balance).
"""
import GA
from fractions import Fraction as F

from tp_premise import premise

L7 = 7
OFF7 = 3
XQS = [F(1, 2), F(1, 3)]
KS = [20, 30]
WEIGHT_SETS = [[F(i - OFF7, 4) for i in range(L7)], [F((i - OFF7) ** 3) for i in range(L7)]]


def popcount(s):
    return bin(s).count("1")


def bilin(a, b, vec):
    out = {}
    for s, c in vec.items():
        if not (s >> b) & 1:
            continue
        sg = -1 if popcount(s & ((1 << b) - 1)) % 2 else 1
        s1 = s & ~(1 << b)
        if (s1 >> a) & 1:
            continue
        sg *= -1 if popcount(s1 & ((1 << a) - 1)) % 2 else 1
        s2 = s1 | (1 << a)
        out[s2] = out.get(s2, F(0)) + sg * c
    return {s: c for s, c in out.items() if c != 0}


def apply(pairs, vec, coef=None):
    out = {}
    for idx, (a, b) in enumerate(pairs):
        w = F(1) if coef is None else coef[idx]
        for s, c in bilin(a, b, vec).items():
            out[s] = out.get(s, F(0)) + w * c
    return {s: c for s, c in out.items() if c != 0}


def cur(m, dag=False):
    return [(i + m, i) for i in range(L7 - m)] if dag else [(i, i + m) for i in range(L7 - m)]


def vsub(u, v):
    out = dict(u)
    for s, c in v.items():
        out[s] = out.get(s, F(0)) - c
    return {s: c for s, c in out.items() if c != 0}


def gibbs(x):
    w = {}
    for s in range(1 << L7):
        p = F(1)
        for i in range(L7):
            if (s >> i) & 1:
                p *= x ** (i - OFF7)
        w[s] = p
    Z = sum(w.values())
    return {s: p / Z for s, p in w.items()}


def expect(rho, ops):
    tot = F(0)
    for s, p in rho.items():
        v = {s: F(1)}
        for op in ops:
            v = apply(op, v)
        tot += p * v.get(s, F(0))
    return tot


def check_edge_identity_on_the_window():
    premise("singularity.bosonisation-bridge-s-wave-sector")
    ok = True
    for m in (1, 2, 3):
        bottom = [(k, k) for k in range(m)]
        top = [(k, k) for k in range(L7 - m, L7)]
        clean = 0
        for s in range(1 << L7):
            v = {s: F(1)}
            lhs = vsub(apply(cur(m), apply(cur(m, True), v)), apply(cur(m, True), apply(cur(m), v)))
            ok = ok and lhs == vsub(apply(bottom, v), apply(top, v))
            if all((s >> k) & 1 for k in range(m)) and not any((s >> k) & 1 for k in range(L7 - m, L7)):
                ok = ok and lhs == {s: F(m)}
                clean += 1
        ok = ok and clean == 2 ** (L7 - 2 * m)
    _tp_rv = (ok); assert _tp_rv is not False, "check_edge_identity_on_the_window"; return _tp_rv


def check_bilinear_subalgebra_invariant_under_boost():
    premise("singularity.bosonisation-bridge-s-wave-sector")
    diag = [(i, i) for i in range(L7)]
    ok = True
    for weights, edge in zip(WEIGHT_SETS, (F(-3, 2), F(-54))):
        # hand value: psi_0^dag psi_6 on |mode 6 occupied> carries weight w_0 - w_6
        v6 = {1 << 6: F(1)}
        img = bilin(0, 6, v6)
        ok = ok and vsub(apply(diag, img, weights), bilin(0, 6, apply(diag, v6, weights))) == \
            {t: edge * c for t, c in img.items()}
        for i in range(L7):
            for j in range(L7):
                for s in range(1 << L7):
                    v = {s: F(1)}
                    lhs = vsub(apply(diag, bilin(i, j, v), weights), bilin(i, j, apply(diag, v, weights)))
                    ok = ok and lhs == {t: (weights[i] - weights[j]) * c for t, c in bilin(i, j, v).items() if i != j}
    _tp_rv = (ok); assert _tp_rv is not False, "check_bilinear_subalgebra_invariant_under_boost"; return _tp_rv


def check_restriction_to_currents_is_kms():
    premise("singularity.q-joint-quasi-freeness-s-wave")
    premise("hawking.kms-restricts-invariant-subalgebras")
    ok = True
    for x in XQS:
        rho = gibbs(x)
        nk = [1 / (x ** (-(i - OFF7)) + 1) for i in range(L7)]
        for s in range(1 << L7):
            p = F(1)
            for i in range(L7):
                p *= nk[i] if (s >> i) & 1 else 1 - nk[i]
            ok = ok and p == rho[s]
        for m in (1, 2):
            am, ad = cur(m), cur(m, True)
            for B in ([ad], [cur(1), cur(1, True)], [ad, am]):
                ok = ok and expect(rho, B + [am]) == x ** (-m) * expect(rho, [am] + B)
    _tp_rv = (ok); assert _tp_rv is not False, "check_restriction_to_currents_is_kms"; return _tp_rv


def check_bose_einstein_occupancy_of_the_currents():
    premise("singularity.bosonisation-bridge-s-wave-sector")
    premise("singularity.q-joint-quasi-freeness-s-wave")
    ok = True
    for x in XQS:
        def n(k):
            return 1 / (x ** (-k) + 1)
        for m in (1, 2, 3):
            ok = ok and all(n(k) - n(k + m) == (x ** (-m) - 1) * n(k + m) * (1 - n(k)) for k in range(-4, 5))
            closed = F(m) / (x ** (-m) - 1)
            nbar = closed / m
            ok = ok and nbar / (1 + nbar) == x ** m
            for K in KS:
                S = sum(n(k + m) * (1 - n(k)) for k in range(-K, K - m + 1))
                edge = sum(n(k) for k in range(-K, -K + m)) - sum(n(k) for k in range(K - m + 1, K + 1))
                ok = ok and S == edge / (x ** (-m) - 1)
                ok = ok and 0 < closed - S <= 2 * m * x ** (K - m) / (1 - x)
        # density matrix against Wick on the 7-mode window
        rho = gibbs(x)
        for m in (1, 2):
            dm = expect(rho, [cur(m), cur(m, True)])
            wick = sum(n(i + m - OFF7) * (1 - n(i - OFF7)) for i in range(L7 - m))
            ok = ok and dm == wick
    _tp_rv = (ok); assert _tp_rv is not False, "check_bose_einstein_occupancy_of_the_currents"; return _tp_rv
